card_mod.style:
:host {
  display: block;
  border-radius: var(--ha-card-border-radius, 12px);
  background: var(--ha-card-background, var(--card-background-color, #fff));
  overflow: hidden;
  padding: 4px 12px 10px 12px;
  box-sizing: border-box;
  {% if state_attr('select.agent_bridge_templatenode_decision','question') %}
  border: 1px solid var(--warning-color);
  animation: cpwait 1.6s ease-in-out infinite;
  {% elif is_state('sensor.agent_bridge_templatenode_status','working') %}
  border: 1px solid var(--primary-color);
  animation: cpwork 1.6s ease-in-out infinite;
  {% elif is_state('sensor.agent_bridge_templatenode_status','agents') or is_state('sensor.agent_bridge_templatenode_status','shell') %}
  /* Waiting on background agents, or on a command it started and has not collected:
     live, but not the session's own work, so the edge is steady rather than
     breathing. */
  border: 1px solid var(--primary-color);
  box-shadow: none;
  animation: none;
  {% else %}
  border: 1px solid var(--divider-color);
  box-shadow: none;
  animation: none;
  {% endif %}
  transition: border 0.4s ease;
}
/* Collapse the 8px the stack puts between children, so the sections butt together
   as one surface instead of floating apart. */
#root > * {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}
@keyframes cpwork {
  0%   { box-shadow: 0 0 6px 0px var(--primary-color); }
  50%  { box-shadow: 0 0 16px 2px var(--primary-color); }
  100% { box-shadow: 0 0 6px 0px var(--primary-color); }
}
@keyframes cpwait {
  0%   { box-shadow: 0 0 6px 0px var(--warning-color); }
  50%  { box-shadow: 0 0 18px 3px var(--warning-color); }
  100% { box-shadow: 0 0 6px 0px var(--warning-color); }
}

ha-card {
  border: none !important;
  box-shadow: none !important;
  background: none !important;
  margin: 0 !important;
  padding: 0 !important;
  width: 100%;
}
.card-content { padding: 0 !important; }

cards.content:
### {% if state_attr('select.agent_bridge_templatenode_decision','question') %}🟡{% elif is_state('sensor.agent_bridge_templatenode_status','working') %}🟢{% elif is_state('sensor.agent_bridge_templatenode_status','agents') or is_state('sensor.agent_bridge_templatenode_status','shell') %}🔵{% else %}⚪{% endif %} __BRIDGE_SESSION_NAME__
*__BRIDGE_MACHINE_NAME__* &bull; status: **{% if state_attr('select.agent_bridge_templatenode_decision','question') %}waiting for you{% else %}{% set st = states('sensor.agent_bridge_templatenode_status') %}{% if st in ['unknown', 'unavailable'] %}ended{% elif st == 'agents' %}waiting for background agents{% elif st == 'shell' %}waiting for background commands{% else %}{{ st }}{% endif %}{% endif %}**{% set act = states('sensor.agent_bridge_templatenode_activity') %}{% set body = state_attr('sensor.agent_bridge_templatenode_activity','response') or '' %}{% if not (body and body.startswith(act.rstrip('.'))) %} &bull; {{ act }}{% endif %}
{% set q = state_attr('select.agent_bridge_templatenode_decision','question') %}{% set resp = state_attr('sensor.agent_bridge_templatenode_activity','response') %}{% if q %}

---
**Waiting on you:**

{{ q }}{% elif resp %}

{% if state_attr('sensor.agent_bridge_templatenode_activity','response_kind') == 'reasoning' %}🧠 {% endif %}{{ resp }}{% endif %}
{% set r = state_attr('sensor.agent_bridge_templatenode_activity','reasoning') %}{% set hist = state_attr('sensor.agent_bridge_templatenode_activity','history') %}{% if r %}<details><summary><em>🧠 reasoning</em></summary>

{{ r }}
</details>{% endif %}{% if hist %}<details><summary><em>recent activity</em></summary>

{% for h in hist[-8:] %}- {{ h }}
{% endfor %}
</details>{% endif %}

